test('v26 migration preserves business data and its readiness gate is included in complete schema',async()=>{
 const name=(await fs.readdir('supabase/migrations')).find(n=>n.endsWith('_fluid_ui_and_rpc_optimization.sql')),sql=await fs.readFile('supabase/migrations/'+name,'utf8'),schema=await fs.readFile('supabase/schema.sql','utf8');assert(schema.includes(sql.trimEnd()));assert(!/select\s+\*/i.test(sql));assert(!/^\s*(delete\s+from|truncate\s|drop\s+table)/im.test(sql));assert(sql.trimEnd().endsWith("notify pgrst, 'reload schema';"));assert(sql.includes('auditSearchReady'));
});
test('v24 P301 metadata labels stay outside value underlines on every page and native Excel labels have no borders',async()=>{
 const record=App.p301Record({settings:{},contractors:[{id:'C',name:'บริษัททดสอบแบบฟอร์ม',phone:'02-123-4567'}]},{id:'R',contract:'ปน.8/2569',contractorId:'C',title:'งานทดสอบ',workCode:'99999',actualCost:100000,acceptanceDate:'2026-03-24',p301:{assetCategory:'ถนน',usefulLifeYears:20,depreciationRate:5}}),labels=['ประเภท','รหัส','ลักษณะ/คุณสมบัติ','รุ่น/แบบ','สถานที่ตั้ง/หน่วยงานที่รับผิดชอบ','ชื่อผู้ขาย/ผู้รับจ้าง/ผู้บริจาค','ที่อยู่','โทรศัพท์'];
 const measure=(text,size)=>Array.from(text).reduce((n,c)=>n+(c===' '?0.2:0.43)*size,0);
 for(const fontSize of [10,16,20]){const doc=App.p301Document(record,{fontSize},measure);assert(doc.pages.length>1);for(const page of doc.pages)for(const labelText of labels){const label=page.commands.find(c=>c.type==='text'&&c.text===labelText);assert(label,labelText);const line=page.commands.find(c=>c.type==='line'&&c.dotted&&Math.abs(c.y-label.y-2)<.01&&c.x>=label.x);assert(line&&line.x>=label.x+measure(labelText,fontSize),labelText+' must not have an underline');}}
 const xml=await App.p301XlsxBlob(record).text(),styleBlock=xml.match(/<cellXfs[^>]*>([\s\S]*?)<\/cellXfs>/)[1],styles=[...styleBlock.matchAll(/<xf\b[^>]*>/g)].map(m=>m[0]);for(const label of labels){const cell=[...xml.matchAll(/<c\b[^>]*>[\s\S]*?<\/c>/g)].map(m=>m[0]).find(c=>c.includes('>'+label+'<'));assert(cell,'native label cell '+label);const style=+(cell.match(/\bs="(\d+)"/)?.[1]||0);assert.match(styles[style],/borderId="0"/,'label cell has no bottom border: '+label);}
 assert(xml.includes('บริษัททดสอบแบบฟอร์ม'));assert(xml.includes('02-123-4567'));
});
test('v23 actual fiscal years use leap denominators, retain inclusive days and one-baht residual',()=>{const input={acquisitionDate:'2024-03-24',totalCost:100000,usefulLifeYears:5,depreciationRate:20,dayCountMethod:'actual'},a=App.calculateP301Schedule(input);assert.equal(a.firstYearBasis,366);assert.equal(a.daysYear1,191);assert.equal(a.rows[1].annualDepreciation,10437.16);assert.equal(a.rows.at(-1).date,'2029-03-23');assert.equal(a.rows.at(-1).days,174);assert.equal(a.rows.at(-1).netBookValue,1);const b=App.calculateP301Schedule({...input,acquisitionDate:'2023-10-02'});assert.equal(b.rows[1].description,'คำนวณ 365 วัน');assert.equal(b.rows[1].annualDepreciation,19945.36);const c=App.calculateP301Schedule({...input,acquisitionDate:'2023-10-01'});assert.equal(c.rows.length,6);assert.equal(c.rows[1].days,366);assert.equal(c.rows[1].description,'คำนวณ 1 ปี');assert.equal(c.rows.at(-1).netBookValue,1);});
test('v23 legacy configured contracts remain 365 while new records use actual and fixed 366 is selectable',()=>{assert.equal(App.p301DayCountMethod({confirmed:true}),'365');assert.equal(App.p301DayCountMethod({}),'actual');assert.equal(App.p301DayCountMethod(),'actual');for(const method of ['actual','365','366'])assert.equal(App.p301DayCountMethod({dayCountMethod:method}),method);const r={id:'r',workCode:'31500',actualCost:100000,acceptanceDate:'2024-03-24'},s={settings:{}};assert.equal(App.p301Record(s,r).dayCountMethod,'actual');assert.equal(App.p301Record(s,{...r,p301:{featureLabel:'-'}}).dayCountMethod,'365');assert.equal(App.p301Record(s,r).modelSpec,'-');const a=App.calculateP301Schedule({acquisitionDate:'2024-03-24',totalCost:100000,usefulLifeYears:5,depreciationRate:20,dayCountMethod:'366'});assert.equal(a.rows[1].annualDepreciation,10437.16);assert.equal(a.rows.at(-1).days,175);assert.equal(a.rows.at(-1).netBookValue,1);assert.throws(()=>App.validateP301Overrides({dayCountMethod:'360'}));assert.throws(()=>App.calculateP301Schedule({acquisitionDate:'2026-04-02',totalCost:10000,usefulLifeYears:5,dayCountMethod:'360'}));});
test('v23 leap acquisition anniversaries stay valid without skipped fiscal depreciation rows',()=>{for(const method of ['actual','365','366']){const a=App.calculateP301Schedule({acquisitionDate:'2024-02-29',totalCost:1234567.89,usefulLifeYears:7,depreciationRate:14.29,dayCountMethod:method});assert.equal(a.rows.at(-1).date,'2031-02-27');assert.equal(a.rows.at(-1).netBookValue,1);assert.equal(Math.round(a.rows.slice(1).reduce((n,r)=>n+r.annualDepreciation,0)*100),123456689);assert(a.rows.every(r=>!r.date.includes('2031-02-29')));}});
test('v23 official catalog has unique hierarchical nodes, separate duplicate code 20000, appendix priority and units',()=>{const c=App.DOH_WORK_CATALOG;assert.equal(c.nodes.length,194);assert.equal(new Set(c.nodes.map(n=>n.id)).size,194);assert.equal(c.nodes.filter(n=>n.code==='20000').length,2);assert.equal(App.workCodePath('31510').node.units[0],'ม.');assert.deepEqual(App.workCodePath('31510').ancestors.map(n=>n.code),['30000','31000','31500','31510']);assert.equal(App.workCodePath('20550').node.name,'งานก่อสร้างสิ่งประกอบ และ/หรือ สาธารณูปโภค');assert.equal(App.workCodePath('20550').node.appendixPage,84);assert(c.nodes.every(n=>!/(มีการแก้ไข|เพิ่มเติมรหัสงาน|ตามภาคผนวก)/.test(n.name)));assert.equal(App.workCodePath('99010').node,null);});
test('v23 P301 uses explicit documented parent codes without rewriting registry codes or guessing unknown codes',()=>{assert.equal(App.depreciationSourceRule('31510'),null);assert.equal(App.depreciationWorkCode('31510'),'31500');assert.equal(App.depreciationWorkCode('31411'),'31410');assert.equal(App.depreciationWorkCode('21111'),'21100');assert.equal(App.depreciationWorkCode('99999'),'99999');const r={id:'r',workCode:'31510',actualCost:9991000,acceptanceDate:'2026-04-02'},d=App.p301Record({settings:{}},r);assert.equal(r.workCode,'31510');assert.equal(d.registryWorkCode,'31510');assert.equal(d.workCode,'31500');assert.equal(d.usefulLifeYears,App.depreciationSourceRule('31500').usefulLifeYears);assert.equal(d.depreciationRate,+(100/d.usefulLifeYears).toFixed(2));});
test('v23 catalog import preserves identities, histories, legacy unknown codes and JSONB repeat no-op',()=>{const base=App.normalizeState({workCodes:[{id:'KEEP',name:'31510'},{id:'UNKNOWN',name:'99010'}],workNames:[{id:'KEEP-JOB',name:'ชื่อที่ใช้งานจริง',codeIds:['KEEP']}],contractRegistry:[],reports:[],settings:{}}),a=App.applyWorkCodeCatalog(base);assert.equal(a.workCodes.find(c=>c.name==='31510').id,'KEEP');assert.equal(a.workNames.find(c=>c.id==='KEEP-JOB').name,'ชื่อที่ใช้งานจริง');assert(a.workCodes.some(c=>c.id==='UNKNOWN'));assert.deepEqual(a.contractRegistry,base.contractRegistry);assert.deepEqual(a.reports,base.reports);assert.deepEqual(App.workspaceChanges(a,App.applyWorkCodeCatalog(a)),{collections:{},values:{}});const reorder=x=>Array.isArray(x)?x.map(reorder):x&&typeof x==='object'?Object.fromEntries(Object.entries(x).reverse().map(([k,v])=>[k,reorder(v)])):x,b=reorder(a);assert.deepEqual(App.workspaceChanges(b,App.applyWorkCodeCatalog(b)),{collections:{},values:{}});});
