test('v23 confirmed weekly entries remain drafts until archive preflight passes with all missing-date causes',()=>{const s={projects:[{id:'p1',contract:'1/2569'},{id:'p2',contract:'2/2569'}],reports:[{id:'r',locked:false,entries:{p1:{plan:100,actual:100,weekly:0,payment:'เบิกจ่ายแล้ว',confirmed:true},p2:{plan:100,actual:100,weekly:0,payment:'เบิกจ่ายแล้ว',confirmed:true}},snapshots:{}}],settings:{}},prev={p1:{actual:100},p2:{actual:100}},before=clone(s),issues=App.weeklyArchiveIssues(s,s.reports[0],prev);assert.equal(issues.length,2);assert(issues.every(x=>x.kind==='dates'));assert.throws(()=>App.archivedWeeklyReport(s,'r',prev),/วันที่เบิกจ่าย/);assert.deepEqual(s,before);for(const e of Object.values(s.reports[0].entries))e.paymentDate='2026-10-21';const archived=App.archivedWeeklyReport(s,'r',prev);assert.equal(archived.locked,true);assert.equal(s.reports[0].locked,false);assert.deepEqual(archived.snapshots.p1,s.projects[0]);assert.throws(()=>App.archivedWeeklyReport({...s,reports:[archived]},'r',prev),/เก็บแล้ว/);});
