test('v22 source pairing is repeatable, preserves master identity and leaves contracts and historical reports intact',()=>{const base=App.normalizeState({workCodes:[{id:'C',name:'11100'}],workNames:[{id:'J',name:'ชื่องานที่เจ้าของกำหนด',codeIds:['C']}],contractRegistry:[],reports:[],settings:{}}),next=App.applyDepreciationSource(base),again=App.applyDepreciationSource(next);assert.deepEqual(base.workCodes.map(x=>x.id),['C']);assert.equal(next.workCodes.find(x=>x.name==='11100').id,'C');assert.equal(next.workNames.find(x=>x.id==='J').name,'ชื่องานที่เจ้าของกำหนด');assert.deepEqual(next.contractRegistry,base.contractRegistry);assert.deepEqual(next.reports,base.reports);assert.deepEqual(App.workspaceChanges(next,again),{collections:{},values:{}});const reorder=x=>Array.isArray(x)?x.map(reorder):x&&typeof x==='object'?Object.fromEntries(Object.entries(x).reverse().map(([k,v])=>[k,reorder(v)])):x,fromJsonb=reorder(next);assert.deepEqual(App.workspaceChanges(fromJsonb,App.applyDepreciationSource(fromJsonb)),{collections:{},values:{}});});
