test('v22 form signatures and executive titles are independent for each funding',()=>{const s=App.normalizeState({settings:{p301:{forms:{DOH:{preparedBy:'หัวหน้างานกรม'},PROVINCE:{preparedBy:'หัวหน้างานจังหวัด'}}},reportForms:{DOH:{title:'รายงานถนน'},PROVINCE:{title:'รายงานพื้นที่'}}}}),r={id:'r',workCode:'31500',actualCost:100000,acceptanceDate:'2026-03-24'};assert.equal(App.p301Record(s,{...r,funding:'DOH'}).preparedBy,'หัวหน้างานกรม');assert.equal(App.p301Record(s,{...r,funding:'PROVINCE'}).preparedBy,'หัวหน้างานจังหวัด');assert(App.reportTitle(s,{funding:'DOH',locked:true},2569).includes('รายงานถนน'));assert(App.reportTitle(s,{funding:'PROVINCE',locked:true},2569).includes('รายงานพื้นที่'));});
test('v22 long multi-road descriptions are retained across continued acquisition pages without losing depreciation rows',()=>{const record=App.p301Record({settings:{}},{id:'r',contract:'ปน.37/2569',workCode:'31500',title:'งานอำนวยความปลอดภัย',actualCost:9991000,acceptanceDate:'2026-04-02',segments:Array.from({length:16},(_,i)=>({routeNumber:String(4000+i),controlSection:'0100',sectionName:'ช่วงทางที่ต้องแสดงครบทุกข้อความ '+i,kmStart:'0+000',kmEnd:'20+000'}))}),doc=App.p301Document(record);assert(doc.pages.length>1);assert.equal(doc.pages.flatMap(x=>x.rows).length,App.calculateP301Schedule(record).rows.length-1);for(let i=0;i<16;i++)assert(doc.pages.some(p=>p.acquisition.description.includes(String(4000+i))));assert(doc.pages.slice(0,-1).every(p=>!p.final));assert.equal(doc.pages.at(-1).rows.at(-1).netBookValue,1);});
