test('v21 P301 pagination repeats acquisition and signs only final page without changing depreciation',()=>{for(const [life,counts]of [[10,[11]],[15,[14,2]]]){const r=App.p301Record({settings:{}},{id:'r',contract:'ปน.5/2569',workCode:'99999',title:'งานติดตั้งราวกันอันตราย',acceptanceDate:'2026-04-02',actualCost:9991000,p301:{assetCategory:'สินทรัพย์โครงสร้างพื้นฐานอื่น',usefulLifeYears:life,depreciationRate:10}}),doc=App.p301Document(r);assert.deepEqual(doc.pages.map(p=>p.rows.length),counts);assert.equal(doc.pages.flatMap(p=>p.rows).length,App.calculateP301Schedule(r).rows.length-1);assert(doc.pages.every(p=>p.acquisition.date===r.acquisitionDate));assert(doc.pages.at(-1).commands.some(c=>c.text?.includes(r.preparedBy)));assert(doc.pages.slice(0,-1).every(p=>!p.commands.some(c=>c.text?.includes(r.preparedBy))));assert.equal(doc.pages.at(-1).rows.at(-1).netBookValue,1);assert.equal(App.P301_COLUMNS.length,12);}});
