test('v21 history deduplicates a multi-road contract, retains full-contract amount and never assigns its quantity to each road',()=>{const s={contractRegistry:[{id:'a',contract:'ปน.1/2569',title:'หลายสาย',year:2569,actualCost:500,quantity:100,unit:'ต้น',segments:[{routeNumber:'42',controlSection:'0100',kmStart:'1+000',kmEnd:'2+000'},{routeNumber:'42',controlSection:'0100',kmStart:'1+000',kmEnd:'2+000'},{routeNumber:'43',controlSection:'0200',kmStart:'0+000',kmEnd:'1+000'}]},{id:'b',contract:'ปน.2/2568',year:2568,segments:[{routeNumber:'42',controlSection:'0100'}]}]},rows=App.assetHistoryRows(s,{routeNumber:'42',controlSection:'0100'});assert.equal(rows.length,2);assert.equal(rows[0].year,2568);const a=rows.find(r=>r.id==='a');assert.equal(a.segments.length,1);assert.equal(a.amount,500);assert.equal(a.quantity,null);assert.equal(a.locationCount,2);const incomplete=App.clone(s);incomplete.contractRegistry[0].segments[2].controlSection='';assert.equal(App.assetHistoryRows(incomplete,{routeNumber:'42',controlSection:'0100'}).find(x=>x.id==='a').quantity,null);assert(a.note.includes('ยอดเงินและปริมาณเป็นยอดรวมสัญญา'));assert.equal(App.assetHistoryRows(s,{routeNumber:'42',controlSection:'0100',year:2568}).length,1);});
