test('P301: ปน.1/2569 inclusive days, full years and exact one-baht residual',()=>{const input={acquisitionDate:'2026-03-24',totalCost:1465628.78,usefulLifeYears:10,depreciationRate:10},before=clone(input),s=App.calculateP301Schedule(input);assert.deepEqual(input,before);assert.equal(s.daysYear1,191);assert.equal(s.rows.length,12);assert.equal(s.rows[0].annualDepreciation,null);assert.equal(s.rows[1].annualDepreciation,76694.55);assert.equal(s.rows[2].annualDepreciation,146562.88);assert.equal(s.rows.at(-1).annualDepreciation,69867.31);assert.equal(s.rows.at(-1).date,'2036-03-23');assert.equal(s.rows.at(-1).days,174);assert.equal(s.rows.at(-1).accumulatedDepreciation,1465627.78);assert.equal(s.rows.at(-1).netBookValue,1);});
