test('P301: status, acceptance-date default, paid total and master contact linkage',()=>{const s={settings:{},contractors:[{id:'C',name:'ผู้รับจ้างทดสอบ',address:'ปัตตานี',phone:'073-000000'}],workCodes:[]},r={id:'R',workCode:'31410',contractorId:'C',contract:'ปน.1/2569',acceptanceDate:'2026-03-24',deliveryDate:'2026-03-01',actualCost:1465628.78,contractValue:2000000};const d=App.p301Record(s,r);assert.equal(d.status,'ready');assert.equal(d.acquisitionDate,r.acceptanceDate);assert.equal(d.totalCost,r.actualCost);assert.equal(d.contractorAddress,'ปัตตานี');assert.equal(d.contractorPhone,'073-000000');assert.equal(App.p301Record(s,{...r,acceptanceDate:''}).status,'pending');assert.equal(App.p301Record(s,{...r,workCode:'22200'}).status,'exempt');assert.equal(App.p301Record(s,{...r,actualCost:0}).totalCost,0);assert(App.p301Record(s,{...r,actualCost:''}).issues.some(x=>x.includes('วงเงิน')));});
