test('P301: registry CSV keeps overrides, missing legacy column preserves existing data and invalid values reject',()=>{const s=registryFixture();normalizeState(s);const r=s.contractRegistry[0];r.p301={note:'ทดสอบ',acquisitionDate:'2026-03-24',usefulLifeYears:10,confirmed:true};const rows=App.parseRegistryCSV(App.registryCSV([r]));assert.deepEqual(rows[0].p301,r.p301);const table=App.parseCSVTable(App.registryCSV([r])),idx=table[0].indexOf('ตั้งค่า พ.3-01 JSON'),q=x=>'"'+String(x??'').replace(/"/g,'""')+'"';const legacy=table.map(row=>row.filter((_,i)=>i!==idx).map(q).join(',')).join('\r\n');assert(!Object.hasOwn(App.parseRegistryCSV(legacy)[0],'p301'));for(const value of [[],{confirmed:'true'},{usefulLifeYears:-1},{recognitionOverride:'unknown'},{acquisitionDate:'2026-02-30'}])assert.throws(()=>App.validateP301Overrides(value));});
test('P301: generated database rules match frontend rules and schema matches ordered migration',async()=>{const migration=await fs.readFile(path.join(root,'supabase/migrations/20261021041807_integrate_sheet_depreciation_and_form_studios.sql'),'utf8'),schema=await fs.readFile(path.join(root,'supabase/schema.sql'),'utf8'),encoded=migration.match(/\$map\$([\s\S]*?)\$map\$/)[1];for(const [code,rule]of Object.entries(JSON.parse(encoded)))assert.deepEqual(rule,App.p301WorkRule(code),code);assert(schema.includes(migration.trimEnd()));assert(!/select\s+\*/i.test(migration));assert(!/for\s+[\s\S]*?loop\s+insert/i.test(migration));assert(migration.trimEnd().endsWith("notify pgrst, 'reload schema';"));});
test('P301: official HTML escapes inputs and xlsx contains separate unique sheets and live contacts',async()=>{const r=App.p301Record({settings:{},contractors:[{id:'C',name:'บริษัท',address:'ที่อยู่จริง',phone:'073123456'}],workCodes:[]},{id:'R',contract:'ปน.1/2569',title:'<script>ทดสอบ</script>',contractorId:'C',workCode:'31410',actualCost:1000,acceptanceDate:'2026-03-24'});const html=App.p301ReportHTML(r);assert(html.includes('ที่อยู่จริง'));assert(html.includes('073123456'));assert(!html.includes('<script>'));assert.equal((html.match(/<th>/g)||[]).length,12);const blob=App.p301XlsxBlob([r,r]),text=await blob.text();assert(text.includes('sheet2.xml'));assert(text.includes('ที่อยู่จริง'));assert(text.includes('073123456'));assert(text.includes('TH SarabunPSK'));assert.throws(()=>App.p301XlsxBlob([]));});
test('v19 progress never compares decoded body bytes with compressed or hidden byte totals',()=>{assert.equal(App.knownTransferSize(new Headers({'content-length':'100'})),0);assert.equal(App.knownTransferSize(new Headers({'content-length':'100','content-encoding':'gzip'})),0);assert.equal(App.knownTransferSize(new Headers({'content-length':'100','content-encoding':'identity'})),100);assert.equal(App.knownTransferSize(new Headers({'content-length':'bad','content-encoding':'identity'})),0);});
