test('v19 migration versions are unique and the release contract is included in ordered migrations',async()=>{const names=(await fs.readdir(path.join(root,'supabase/migrations'))).filter(f=>f.endsWith('.sql'));assert(names.every(f=>/^\d{14}_[\p{L}\p{N}_-]+\.sql$/u.test(f)));assert.equal(new Set(names.map(f=>f.slice(0,14))).size,names.length);const body=await fs.readFile(path.join(root,'supabase/migrations',names.sort().at(-1)),'utf8');assert.match(body,/pn2_release_compatibility/);assert.match(body,/notify pgrst, 'reload schema'/);});
