test('v16 link audit and draft fill preserve entries and closed snapshots, and repeat without duplicates',()=>{const s=registryFixture();normalizeState(s);const range={start:'2026-10-06',end:'2026-10-12',reference:'2026-10-12'},r=createReport(s,range,2570,'PROVINCE');s.reports.push(r);const pid=Object.keys(r.entries)[0];r.entries[pid].note='เก็บหมายเหตุ';const closed={...clone(r),id:'CLOSED',locked:true,end:'2026-10-05',snapshots:{[pid]:clone(s.projects.find(p=>p.id===pid))}};s.reports.unshift(closed);const frozen=clone(closed),existing=clone(r.entries);s.contractRegistry.push({...clone(s.contractRegistry[0]),id:'G2',projectId:'',contract:'ปน.3/2570'});assert.equal(App.reportLinkAudit(s,r).missing.length,1);assert.equal(App.fillMissingReportContracts(s,r.id),1);assert.equal(App.fillMissingReportContracts(s,r.id),0);assert.deepEqual(s.reports.find(x=>x.id==='CLOSED'),frozen);for(const [id,e]of Object.entries(existing))assert.deepEqual(r.entries[id],e);assert.throws(()=>App.fillMissingReportContracts(s,'CLOSED'),/ปิดแล้ว/);});
