test('executive geometry shares middle columns and reserves remaining province width for remarks',()=>{const s=registryFixture();normalizeState(s);const r=createReport(s,{start:'2026-10-06',end:'2026-10-12',reference:'2026-10-12'},2570,'PROVINCE');s.reports.push(r);const a=App.reportLayout(s,r,2570);assert.deepEqual(a.pixels.slice(2,11),App.widths.slice(2,11).map(w=>w*11));assert(a.pixels[11]>=App.widths[11]*11-.00001);assert(Math.abs(a.widths.reduce((a,b)=>a+b,0)-100)<.001);assert(a.total>=1100-.00001);const pid=Object.keys(r.entries)[0];r.snapshots={...r.snapshots,[pid]:{...s.projects.find(p=>p.id===pid),title:'ชื่อโครงการทดสอบที่ยาวมาก '.repeat(25)}};r.locked=true;const longer=App.reportLayout(s,r,2570);assert(longer.pixels[1]>a.pixels[1]);assert(longer.total>a.total);assert.deepEqual(longer.pixels.slice(2,11),a.pixels.slice(2,11));assert(App.reportHTML(s,r,2570).includes('auto-report'));const before=[4,21,6,6,5,5,12,7,5,5,5,19].map((w,i)=>w*App.widthFactors[i]*[1,.8,.9,.9,1,.9,1,1,.8,.8,.8,1.2][i]);assert(Math.abs(App.widths[0]-(before[0]/before.reduce((a,b)=>a+b,0)*100)*1.07)<.00001);for(const funding of ['DOH','PROVINCE']){const title=App.reportTitle({...s,activeFunding:funding},{...r,funding},2570);assert(!title.includes(' · '));assert(!title.includes('งบจังหวัด'));assert(!title.includes('กรมทางหลวง')); assert(title.includes('2570'));}});

